    <!-- CONFIRMATION -->
    <div class="step" id="step-confirmation" role="region" aria-label="Confirmation">
      <div class="confirmation">
        <div class="confirmation-icon">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
        </div>
        <h1 class="confirmation-title">Registration Received</h1>
        <p class="confirmation-subtitle">Your enterprise registration has been submitted successfully.</p>
        <div class="confirmation-card" id="confirmation-card"></div>
        <div class="next-steps">
          <div class="next-steps-title">Next Steps</div>
          <div class="next-steps-text">1. Verify your email address
2. Verify your phone number
3. Complete KYC and AML verification
4. Await enterprise review by IVX Holdings</div>
        </div>
        <a href="/login" class="btn-done" style="text-decoration:none;display:flex;align-items:center;justify-content:center;">Continue to Login</a>
      </div>
    </div>
  </div>

  <script>
  (function() {
    'use strict';

    // ─── Config ────────────────────────────────────────────────────────
    var API_BASE = '__IVX_API_BASE_URL__'.replace(/\/$/, '');
    if (API_BASE.indexOf('__IVX_') === 0 || !API_BASE) {
      API_BASE = 'https://api.ivxholding.com';
    }
    var MEMBER_REGISTER_URL = API_BASE + '/api/members/register';
    var ENTERPRISE_REGISTER_URL = API_BASE + '/api/ivx/enterprise-registration/register';
    var DRAFT_KEY = 'ivx_enterprise_registration_draft';
    var DRAFT_EXPIRY_MS = 24 * 60 * 60 * 1000;

    // ─── Role options ──────────────────────────────────────────────────
    var ROLES = [
      { id: 'enterprise', label: 'Enterprise', desc: 'Register a company entity as the primary account holder.' },
      { id: 'investor', label: 'Investor', desc: 'Capital partner seeking real estate investment opportunities.' },
      { id: 'buyer', label: 'Buyer', desc: 'Acquiring properties directly through the platform.' },
      { id: 'jv_partner', label: 'JV Partner', desc: 'Joint venture partnership for shared deals.' },
      { id: 'tokenized_interest', label: 'Tokenized Interest', desc: 'Fractional tokenized property interests.' },
      { id: 'broker_agent', label: 'Broker or Agent', desc: 'Licensed broker or agent facilitating transactions.' },
      { id: 'lender', label: 'Lender', desc: 'Providing capital or financing for deals.' },
      { id: 'vendor_contractor', label: 'Vendor or Contractor', desc: 'Service provider for real estate projects.' },
    ];

    // ─── State ─────────────────────────────────────────────────────────
    var state = {
      currentStep: 0, // 0=account, 1=role, 2=enterprise, 3=review, 4=confirmation
      formValues: {},
      isSubmitting: false,
      idempotencyKey: '',
      result: { enterpriseId: '', authUserId: '', traceId: '' },
    };

    function generateIdempotencyKey() {
      return 'ivx-ent-web-' + Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 10);
    }
    state.idempotencyKey = generateIdempotencyKey();

    // ─── Validation ────────────────────────────────────────────────────
    function validateEmail(email) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim().toLowerCase());
    }
    function validatePhone(phone) {
      return /^\+?[\d\s\-()]{10,}$/.test(phone.trim());
    }
    function validatePassword(pw) {
      if (pw.length < 12) return 'Password must be at least 12 characters.';
      if (pw.length > 128) return 'Password must be at most 128 characters.';
      if (!/[A-Z]/.test(pw)) return 'Password must contain at least 1 uppercase letter.';
      if (!/[0-9]/.test(pw)) return 'Password must contain at least 1 number.';
      return null;
    }
    function validateWebsite(url) {
      if (!url.trim()) return true;
      try { new URL(url.startsWith('http') ? url : 'https://' + url); return true; } catch(e) { return false; }
    }
    function validateZip(zip) { return /^[A-Za-z0-9\s\-]{3,10}$/.test(zip.trim()); }

    function validateStep1() {
      var errors = {};
      var v = state.formValues;
      if (!v.firstName || !v.firstName.trim()) errors.firstName = 'First name is required.';
      if (!v.lastName || !v.lastName.trim()) errors.lastName = 'Last name is required.';
      if (!v.email || !v.email.trim()) errors.email = 'Email is required.';
      else if (!validateEmail(v.email)) errors.email = 'Please enter a valid email address.';
      if (!v.phone || !v.phone.trim()) errors.phone = 'Phone number is required.';
      else if (!validatePhone(v.phone)) errors.phone = 'Please enter a valid phone number.';
      var pwErr = validatePassword(v.password || '');
      if (pwErr) errors.password = pwErr;
      if (!v.dateOfBirth || !v.dateOfBirth.trim()) errors.dateOfBirth = 'Date of birth is required.';
      if (!v.gender) errors.gender = 'Gender is required.';
      if (!v.zipCode || !v.zipCode.trim()) errors.zipCode = 'ZIP / postal code is required.';
      else if (!validateZip(v.zipCode)) errors.zipCode = 'Please enter a valid ZIP / postal code.';
      if (!v.acceptTerms) errors.acceptTerms = 'You must accept the Terms of Service.';
      if (!v.acceptPrivacy) errors.acceptPrivacy = 'You must accept the Privacy Policy.';
      return errors;
    }

    function validateStep2() {
      var errors = {};
      if (!state.formValues.primaryRole) errors.primaryRole = 'Please select a primary role.';
      return errors;
    }

    function validateStep3() {
      var errors = {};
      var v = state.formValues;
      if (!v.legalName || v.legalName.trim().length < 2) errors.legalName = 'Legal company name is required (minimum 2 characters).';
      if (!v.displayName || !v.displayName.trim()) errors.displayName = 'Display company name is required.';
      if (!v.companyType) errors.companyType = 'Please select a company type.';
      if (!v.industry) errors.industry = 'Please select an industry.';
      if (v.website && v.website.trim() && !validateWebsite(v.website)) errors.website = 'Please enter a valid website URL.';
      if (!v.address || !v.address.trim()) errors.address = 'Business address is required.';
      if (!v.city || !v.city.trim()) errors.city = 'City is required.';
      if (!v.state || !v.state.trim()) errors.state = 'State / province is required.';
      if (!v.postalCode || !v.postalCode.trim()) errors.postalCode = 'ZIP / postal code is required.';
      else if (!validateZip(v.postalCode)) errors.postalCode = 'Please enter a valid ZIP / postal code.';
      if (!v.authorizedRepresentative || v.authorizedRepresentative.trim().length < 2) errors.authorizedRepresentative = 'Authorized representative is required.';
      if (!v.representativeTitle || !v.representativeTitle.trim()) errors.representativeTitle = 'Representative title is required.';
      var teamSize = parseInt(v.teamSize, 10);
      if (!v.teamSize || isNaN(teamSize) || teamSize < 1 || teamSize > 100000) errors.teamSize = 'Team size must be a number between 1 and 100,000.';
      if (!v.businessCategory) errors.businessCategory = 'Please select a business category.';
      return errors;
    }

    // ─── Error display ─────────────────────────────────────────────────
    function showErrors(errors) {
      // Clear all
      var allErrDivs = document.querySelectorAll('[id^="err-"]');
      allErrDivs.forEach(function(d) { d.style.display = 'none'; d.textContent = ''; });
      // Show new
      Object.keys(errors).forEach(function(field) {
        var el = document.getElementById('err-' + field);
        if (el) {
          el.textContent = errors[field];
          el.style.display = 'flex';
          // Mark input wrapper
          var input = document.getElementById(field);
          if (input && input.closest) {
            var wrapper = input.closest('.input-wrapper');
            if (wrapper) wrapper.classList.add('error');
          }
        }
      });
    }

    function clearInputError(field) {
      var el = document.getElementById('err-' + field);
      if (el) { el.style.display = 'none'; el.textContent = ''; }
      var input = document.getElementById(field);
      if (input && input.closest) {
        var wrapper = input.closest('.input-wrapper');
        if (wrapper) wrapper.classList.remove('error');
      }
    }

    // ─── Collect form values ───────────────────────────────────────────
    function collectFormValues() {
      var ids = ['firstName','lastName','email','phone','password','dateOfBirth','gender',
        'country','zipCode','acceptTerms','acceptPrivacy',
        'legalName','displayName','companyType','industry','website','address','city','state',
        'postalCode','teamSize','authorizedRepresentative','representativeTitle','businessCategory'];
      var vals = {};
      ids.forEach(function(id) {
        var el = document.getElementById(id);
        if (!el) return;
        if (el.type === 'checkbox') vals[id] = el.checked;
        else vals[id] = el.value;
      });
      vals.primaryRole = state.formValues.primaryRole || '';
      state.formValues = vals;
    }

    // ─── Step navigation ───────────────────────────────────────────────
    var STEP_NAMES = ['account', 'role', 'enterprise', 'review', 'confirmation'];
    var stepDivs = ['step-account','step-role','step-enterprise','step-review','step-confirmation'];

    function showStep(index) {
      stepDivs.forEach(function(id, i) {
        var el = document.getElementById(id);
        if (el) el.classList.toggle('active', i === index);
      });
      state.currentStep = index;
      updateProgress(index);
      // Save draft (except confirmation)
      if (index < 4) saveDraft();
      // Browser history support
      var hash = '#' + STEP_NAMES[index];
      if (window.location.hash !== hash) {
        history.pushState({ step: index }, '', hash);
      }
      window.scrollTo(0, 0);
    }

    function updateProgress(stepIndex) {
      var visibleSteps = 3;
      var effective = stepIndex >= 3 ? visibleSteps : stepIndex;
      for (var i = 0; i < visibleSteps; i++) {
        var circle = document.getElementById('prog-circle-' + i);
        var label = document.getElementById('prog-label-' + i);
        if (!circle || !label) continue;
        circle.classList.remove('complete', 'current');
        label.classList.remove('current');
        if (i < effective) { circle.classList.add('complete'); circle.innerHTML = '&#10003;'; }
        else if (i === effective) { circle.classList.add('current'); circle.textContent = (i + 1); }
        else { circle.textContent = (i + 1); }
        if (i === effective) label.classList.add('current');
        var line = document.getElementById('prog-line-' + i);
        if (line) line.classList.toggle('complete', i < effective);
      }
      // Hide progress bar on confirmation
      var progBar = document.getElementById('progress-bar');
      if (progBar) progBar.style.display = stepIndex >= 4 ? 'none' : 'flex';
    }

    function goNext() {
      collectFormValues();
      if (state.currentStep === 0) {
        var errs1 = validateStep1();
        if (Object.keys(errs1).length > 0) { showErrors(errs1); return; }
        showStep(1);
      } else if (state.currentStep === 1) {
        var errs2 = validateStep2();
        if (Object.keys(errs2).length > 0) { showErrors(errs2); return; }
        showStep(2);
      } else if (state.currentStep === 2) {
        var errs3 = validateStep3();
        if (Object.keys(errs3).length > 0) { showErrors(errs3); return; }
        renderReview();
        showStep(3);
      }
    }

    function goBack() {
      if (state.currentStep > 0 && state.currentStep < 4) {
        showStep(state.currentStep - 1);
      } else if (state.currentStep === 0) {
        window.location.href = '/';
      }
    }

    // ─── Render role cards ─────────────────────────────────────────────
    function renderRoleCards() {
      var grid = document.getElementById('role-grid');
      if (!grid) return;
      grid.innerHTML = '';
      ROLES.forEach(function(role) {
        var card = document.createElement('div');
        card.className = 'role-card';
        card.setAttribute('role', 'button');
        card.setAttribute('tabindex', '0');
        card.setAttribute('aria-label', 'Select role: ' + role.label);
        card.innerHTML =
          '<div class="role-card-header">' +
            '<div class="role-radio"><div class="role-radio-dot"></div></div>' +
            '<div class="role-label">' + role.label + '</div>' +
          '</div>' +
          '<div class="role-desc">' + role.desc + '</div>';
        var selectRole = function() {
          state.formValues.primaryRole = role.id;
          document.querySelectorAll('.role-card').forEach(function(c) { c.classList.remove('selected'); });
          card.classList.add('selected');
          clearInputError('primaryRole');
        };
        card.addEventListener('click', selectRole);
        card.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectRole(); } });
        grid.appendChild(card);
      });
    }

    // ─── Render review ─────────────────────────────────────────────────
    function renderReview() {
      var v = state.formValues;
      var roleLabel = (ROLES.find(function(r) { return r.id === v.primaryRole; }) || {}).label || v.primaryRole;
      var companyTypeLabel = v.companyType;
      var typeMap = { llc: 'LLC', c_corp: 'C Corporation', s_corp: 'S Corporation', partnership: 'Partnership', sole_proprietor: 'Sole Proprietor', trust: 'Trust', nonprofit: 'Nonprofit', other: 'Other' };
      if (typeMap[v.companyType]) companyTypeLabel = typeMap[v.companyType];

      var html = '';
      html += '<div class="review-section"><div class="review-section-title">Account</div>';
      html += reviewRow('Name', v.firstName + ' ' + v.lastName);
      html += reviewRow('Email', v.email);
      html += reviewRow('Phone', v.phone);
      html += reviewRow('Country', v.country);
      html += '</div>';
      html += '<div class="review-section"><div class="review-section-title">Role</div>';
      html += reviewRow('Primary Role', roleLabel);
      html += '</div>';
      html += '<div class="review-section"><div class="review-section-title">Enterprise</div>';
      html += reviewRow('Legal Name', v.legalName);
      html += reviewRow('Display Name', v.displayName);
      html += reviewRow('Company Type', companyTypeLabel);
      html += reviewRow('Industry', v.industry);
      html += reviewRow('Website', v.website);
      html += reviewRow('Address', v.address + ', ' + v.city + ', ' + v.state + ' ' + v.postalCode);
      html += reviewRow('Representative', v.authorizedRepresentative + ' (' + v.representativeTitle + ')');
      html += reviewRow('Team Size', v.teamSize);
      html += reviewRow('Business Category', v.businessCategory);
      html += '</div>';
      var el = document.getElementById('review-content');
      if (el) el.innerHTML = html;
    }

    function reviewRow(label, val) {
      return '<div class="review-row"><div class="review-label">' + label + '</div><div class="review-value">' + (val || '—') + '</div></div>';
    }

    // ─── Draft storage ─────────────────────────────────────────────────
    function saveDraft() {
      collectFormValues();
      var v = state.formValues;
      var draft = {
        formValues: {},
        currentStep: state.currentStep,
        draftUpdatedAt: new Date().toISOString(),
        idempotencyKey: state.idempotencyKey,
      };
      // Copy all except password
      Object.keys(v).forEach(function(k) {
        if (k === 'password') draft.formValues.passwordEntered = !!v.password;
        else draft.formValues[k] = v[k];
      });
      try { localStorage.setItem(DRAFT_KEY, JSON.stringify(draft)); } catch(e) {}
    }

    function loadDraft() {
      try {
        var raw = localStorage.getItem(DRAFT_KEY);
        if (!raw) return null;
        var draft = JSON.parse(raw);
        var updated = new Date(draft.draftUpdatedAt).getTime();
        if (isNaN(updated) || Date.now() - updated > DRAFT_EXPIRY_MS) {
          localStorage.removeItem(DRAFT_KEY);
          return null;
        }
        return draft;
      } catch(e) { return null; }
    }

    function clearDraft() {
      try { localStorage.removeItem(DRAFT_KEY); } catch(e) {}
    }

    function restoreDraft(draft) {
      if (!draft || !draft.formValues) return;
      var fv = draft.formValues;
      Object.keys(fv).forEach(function(k) {
        if (k === 'passwordEntered') return;
        var el = document.getElementById(k);
        if (!el) return;
        if (el.type === 'checkbox') el.checked = !!fv[k];
        else el.value = fv[k] || '';
      });
      state.formValues.primaryRole = fv.primaryRole || '';
      if (fv.primaryRole) {
        var cards = document.querySelectorAll('.role-card');
        cards.forEach(function(c, i) {
          if (ROLES[i] && ROLES[i].id === fv.primaryRole) c.classList.add('selected');
        });
      }
      state.idempotencyKey = draft.idempotencyKey || state.idempotencyKey;
      var startStep = draft.currentStep && draft.currentStep < 3 ? draft.currentStep : 0;
      if (startStep > 0) showStep(startStep);
    }

    // ─── Error message mapping ─────────────────────────────────────────
    function userFriendlyError(code, fallback) {
      var map = {
        INVALID_INPUT: 'Please check all required fields and try again.',
        DUPLICATE_ENTERPRISE: 'An enterprise with this legal name or website already exists.',
        DUPLICATE_LEGAL_NAME: 'An enterprise with this legal name already exists.',
        DUPLICATE_DOMAIN: 'An enterprise with this website domain already exists.',
        CREATION_FAILED: 'We could not create the enterprise. Please try again.',
        MEMBERSHIP_FAILED: 'Enterprise created, but membership binding failed. Contact support.',
        NOT_AUTHORIZED: 'You are not authorized to perform this action.',
        INVALID_EMAIL: 'This email is already registered. Please sign in instead.',
        WEAK_PASSWORD: 'Password does not meet the minimum requirements.',
        AUTH_CREATION_FAILED: 'A previous attempt is still processing. Please wait and try again.',
        UNKNOWN_ERROR: 'An unexpected error occurred. Please try again.',
      };
      return map[code] || fallback || 'An error occurred. Please try again.';
    }

    // ─── Submit ────────────────────────────────────────────────────────
    function showServerError(msg) {
      var el = document.getElementById('review-server-error');
      if (el) {
        el.innerHTML = '<div class="server-error"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>' + msg + '</div>';
      }
    }

    async function handleSubmit() {
      if (state.isSubmitting) return; // Double-submit protection
      state.isSubmitting = true;
      var btn = document.getElementById('btn-submit');
      var txt = document.getElementById('submit-text');
      if (btn) btn.disabled = true;
      if (txt) txt.innerHTML = '<span class="spinner"></span>';

      collectFormValues();
      var v = state.formValues;

      // Hide previous error
      var errEl = document.getElementById('review-server-error');
      if (errEl) errEl.innerHTML = '';

      try {
        // STEP 1: Register individual member
        var individualResp = await fetch(MEMBER_REGISTER_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            email: v.email.trim().toLowerCase(),
            password: v.password,
            firstName: v.firstName.trim(),
            lastName: v.lastName.trim(),
            dateOfBirth: v.dateOfBirth,
            gender: v.gender,
            phone: v.phone.trim(),
            country: v.country,
            zipCode: v.zipCode.trim(),
            roles: [v.primaryRole],
            acceptTerms: v.acceptTerms,
            registrationRequestId: state.idempotencyKey,
          }),
        });
        var individualResult = await individualResp.json().catch(function() { return {}; });

        if (!individualResult.ok || !individualResult.authUserId) {
          var errMsg = userFriendlyError(individualResult.code || '', individualResult.message || individualResult.error || 'Registration failed.');
          showServerError(errMsg);
          state.isSubmitting = false;
          if (btn) btn.disabled = false;
          if (txt) txt.textContent = 'Submit Registration';
          return;
        }

        var authUserId = individualResult.authUserId;

        // STEP 2: Register enterprise
        var enterpriseResp = await fetch(ENTERPRISE_REGISTER_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            ownerAuthUserId: authUserId,
            legalName: v.legalName.trim(),
            displayName: v.displayName.trim(),
            companyType: v.companyType,
            industry: v.industry,
            website: v.website.trim(),
            address: v.address.trim() + ', ' + v.city.trim() + ', ' + v.state.trim() + ' ' + v.postalCode.trim() + ', ' + (v.country || ''),
            authorizedRepresentative: v.authorizedRepresentative.trim(),
            representativeJobTitle: v.representativeTitle.trim(),
            teamSize: parseInt(v.teamSize, 10) || 1,
            businessCategory: v.businessCategory,
            sourceChannel: 'enterprise_registration_web',
            traceId: individualResult.traceId,
          }),
        });
        var enterpriseResult = await enterpriseResp.json().catch(function() { return {}; });

        if (!enterpriseResult.ok || !enterpriseResult.enterpriseId) {
          var entErrMsg = userFriendlyError(enterpriseResult.errorCode || '', enterpriseResult.error || 'Enterprise registration failed.');
          showServerError(entErrMsg);
          state.isSubmitting = false;
          if (btn) btn.disabled = false;
          if (txt) txt.textContent = 'Submit Registration';
          return;
        }

        // Success — clear draft, show confirmation
        clearDraft();
        state.result.enterpriseId = enterpriseResult.enterpriseId;
        state.result.authUserId = authUserId;
        state.result.traceId = enterpriseResult.traceId;
        renderConfirmation();
        showStep(4);

      } catch (err) {
        var msg = err && err.message ? err.message : 'Network error. Please check your connection and try again.';
        showServerError(userFriendlyError('', msg));
      } finally {
        state.isSubmitting = false;
        if (btn) btn.disabled = false;
        if (txt) txt.textContent = 'Submit Registration';
      }
    }

    function renderConfirmation() {
      var v = state.formValues;
      var card = document.getElementById('confirmation-card');
      if (!card) return;
      card.innerHTML =
        '<div class="confirmation-card-title">Enterprise Details</div>' +
        confirmRow('Enterprise Name', v.legalName) +
        confirmRow('Member Name', v.firstName + ' ' + v.lastName) +
        confirmRow('Registration Status', 'Pending Verification') +
        confirmRow('Email Verification', 'Not Verified') +
        confirmRow('Phone Verification', 'Not Verified') +
        confirmRow('Enterprise Review', 'Not Started') +
        '<div class="confirmation-divider"></div>' +
        confirmRow('Enterprise ID', state.result.enterpriseId, true) +
        confirmRow('Auth User ID', state.result.authUserId, true) +
        confirmRow('Trace ID', state.result.traceId, true);
    }

    function confirmRow(label, val, mono) {
      var valClass = mono ? 'confirmation-mono' : 'confirmation-value';
      return '<div class="confirmation-row"><div class="confirmation-label">' + label + '</div><div class="' + valClass + '">' + (val || '—') + '</div></div>';
    }

    // ─── Event listeners ───────────────────────────────────────────────
    document.addEventListener('DOMContentLoaded', function() {
      renderRoleCards();

      // Password toggle
      var pwToggle = document.getElementById('pw-toggle');
      var pwInput = document.getElementById('password');
      var pwEye = document.getElementById('pw-eye');
      if (pwToggle && pwInput) {
        pwToggle.addEventListener('click', function() {
          pwInput.type = pwInput.type === 'password' ? 'text' : 'password';
          if (pwEye) {
            pwEye.innerHTML = pwInput.type === 'password'
              ? '<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>'
              : '<path d="M17.94 17.94c-.6.6-1.3 1.1-2.06 1.5"/><path d="M1 1l22 22"/><path d="M9.9 4.24c.7-.16 1.4-.24 2.1-.24 7 0 11 8 11 8a13.16 13.16 0 0 1-1.67 2.68"/><path d="M6.06 6.06A13.16 13.16 0 0 0 1 12s4 8 11 8a13.16 13.16 0 0 0 5.94-1.94"/>';
          }
        });
      }

      // Clear error on input
      var inputs = document.querySelectorAll('.input, select.input');
      inputs.forEach(function(input) {
        input.addEventListener('input', function() { clearInputError(input.id); });
        input.addEventListener('change', function() { clearInputError(input.id); });
      });

      // Buttons
      var btnNext1 = document.getElementById('btn-next-1');
      if (btnNext1) btnNext1.addEventListener('click', goNext);
      var btnNext2 = document.getElementById('btn-next-2');
      if (btnNext2) btnNext2.addEventListener('click', goNext);
      var btnReview3 = document.getElementById('btn-review-3');
      if (btnReview3) btnReview3.addEventListener('click', function() {
        collectFormValues();
        var errs = validateStep3();
        if (Object.keys(errs).length > 0) { showErrors(errs); return; }
        renderReview();
        showStep(3);
      });
      var btnBack2 = document.getElementById('btn-back-2');
      if (btnBack2) btnBack2.addEventListener('click', goBack);
      var btnBack3 = document.getElementById('btn-back-3');
      if (btnBack3) btnBack3.addEventListener('click', goBack);
      var btnBackReview = document.getElementById('btn-back-review');
      if (btnBackReview) btnBackReview.addEventListener('click', goBack);
      var btnSubmit = document.getElementById('btn-submit');
      if (btnSubmit) btnSubmit.addEventListener('click', handleSubmit);

      // Browser back/forward
      window.addEventListener('popstate', function(e) {
        var step = (e.state && typeof e.state.step === 'number') ? e.state.step : 0;
        if (step >= 0 && step < 5) showStep(step);
      });

      // Restore draft
      var draft = loadDraft();
      if (draft) restoreDraft(draft);

      // Set initial hash
      if (window.location.hash) {
        var hashStep = window.location.hash.replace('#', '');
        var stepIdx = STEP_NAMES.indexOf(hashStep);
        if (stepIdx >= 0 && stepIdx < 4) showStep(stepIdx);
      }
    });
  })();
  </script>
</body>
</html>
